prompt:
Reimplement the built-in `Readonly<T>` utility type.

**Requirements:**
- Declare and export `MyReadonly<T>` so every property of `T` becomes `readonly`.

**Example:**
```ts
type A = MyReadonly<{ a: number; b: string }>;
// => { readonly a: number; readonly b: string }
```

files.content:
// Type-level assertion helpers for ts-types-drills.
// Adapted from type-challenges (https://github.com/type-challenges/type-challenges) — MIT.

export type Expect<T extends true> = T;

export type Equal<X, Y> = (<T>() => T extends X ? 1 : 2) extends <T>() => T extends Y ? 1 : 2
  ? true
  : false;

export type NotEqual<X, Y> = Equal<X, Y> extends true ? false : true;

export type NotAny<T> = [T] extends [never] ? false : 0 extends 1 & T ? false : true;

import type { Expect, Equal } from './type-utils.js';

export type MyReadonly<T> = { readonly [P in keyof T]: T[P] };

type cases = [
  Expect<Equal<MyReadonly<{ a: number }>, { readonly a: number }>>,
  Expect<
    Equal<MyReadonly<{ a: number; b: string }>, { readonly a: number; readonly b: string }>
  >,
];

export type { cases };
